  ('7b1799c7-9958-412d-8e80-ef468c398a72', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और हीन भी इतनी कि मेरा कहीं भी और कोई भी अपमान कर सकता है— एक मामूली अपराधी की तरह।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1dc42287-3815-4ba5-bf48-5bba80caf191', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और मुझे यह भी अधिकार नहीं कि मैं उस अपमान का बदला लेना तो दूर रहा, उसके लिए कहीं अपील या दया-प्रार्थना ही कर सकूँ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7ae057e5-948d-43df-b375-4a1d32026ae2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$क्या कोई भूकंप आया था, जिससे दीवार में दरार पड़ गई? बड़े महत्व का प्रश्न है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c7defbe0-55bc-4e75-88bb-ded41b2b8d9a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस अर्थ में भी कि यह बात को खिलने का, आगे बढ़ने का अवसर देता है और इस अर्थ में भी कि ठीक समय पर पूछा गया है। ऐसे प्रश्नों का उत्तर देने में एक अपूर्व आनंद आता है, तो उत्तर यह है आपके प्रश्न का—$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d52e15ef-bc46-4bf2-a994-2e1fd8ea536e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जी हाँ, एक भूकंप आया था, जिससे दीवार में दरार पड़ गई और लीजिए आपको कोई नया प्रश्न न पूछना पड़े, इसलिए मैं अपनी ओर से ही कह रहा हूँ कि यह दीवार थी मानसिक विचारों की;$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4f1d18b6-4373-4540-be55-c1dd5346d805', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसलिए यह भूकंप भी किसी प्रांत या प्रदेश में नहीं उठा, मेरे मानस में ही उठा था। मैं और मेरा देश$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0dffba07-2c8f-4f70-9ea7-88ac0b18fa17', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मानस में भूकंप उठा था? हाँ जी, मानस में भूकंप उठा था और भूकंप में क्या कोई धरती थोड़े ही हिली थी, आकाश थोड़े ही काँपा था, एक तेजस््ववीवी पुरुष का अनुभवव ही वह भूकंप था, जिसने मुझे हिला दिया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e57c3c9e-cdb3-4ca5-a914-dfdb17130eee', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ववे तेजस््ववीवी पुरुष थे स््वर्गीय पंजाब-केसरी लाला लाजपत राय। अपने महान राष्‍ट्र की पराधीनता के दीन दिनों में जिन लोगों ने अपने रक्त से गौरवव के दीपक जलाए और जो घोर अंधकार और भयंकर बववंडरों के झकझोरों में जीवन-भर खेल, उन दीपकों को बुझने से बचाते रहे, उन््हीं में एक थे लालाजी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e3c87fc4-2297-489b-b2f6-ded9d0cd8d2f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनकी कलम और ववाणी दोनों में तेजस््वविता की अद्भुत किरणें थीं। ववे उन््हीं दिनों सारे संसार में घूमे थे। उनके व््यक्‍त‍ित््वव के गठन में, उनके परिववार, उनके पास-पड़़ोस और उनके नगर ने अपने सर्वोत्तम रत््नों की ज््ययोति उन््हें भेंटट दी थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6287634c-e454-4f1a-85eb-947ee228a440', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अजी, क्या बात थी उनके व््यक्‍त‍ित््वव की, क्या देखने में, क्या सुनने में! ववे एक अपूर््व मनुष्य थे। कौन था दुनिया में जिस पर ववे मिलते ही छा न जाते, पर संसार के देशों में घूमकर ववे अपने देश में लौटटे, तो उन््होंने अपना सारा अनुभवव एक ही ववाक्य में भरकर बिखेर दिया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('199737a9-68ae-4a82-9512-2b12dcc7949a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह अनुभवव ही तो वह भूकंप था, जिसने मेरी पूर््णता को एक ही ठसक में अपूर््णता की कसक से भर दिया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9e076704-5b1a-4e20-af48-95464ca89621', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनका वह अनुभवव था कि “मैं अमेरिका गया, इंग््लैंड गया, फ््राांस गया और संसार के दूसरे देशों में भी घूमा, पर जहाँ भी मैं गया, भारतवर््ष की गुलामी की लज्जा का कलंक मेरे माथे पर लगा रहा।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2a98ecd9-ece8-4963-8d7d-97876d04b6eb', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$क्या सचमुच यह अनुभवव एक मानसिक भूकंप नहीं हैहै, जो मनुष्य को झकझोर कर कहे कि किसी मनुष्य के पास संसार के ही नहीं, यदि स््वर््ग के भी सब उपहार और साधन हों, पर उसका देश गुलाम हो या किसी भी दूसरे रूप में हीन हो तो ववे सारे उपहार और साधन उसे गौरवव नहीं दे सकते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ff1a069d-ae9e-4755-b186-516e94fd5d8c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस अनुभवव की छाया में मैं सोचता हूँ कि मेरा कर््तव्य हैहै कि मुझे निजी रूप में सारे संसार का राज्य भी क््यों न मिलता हो, मैं कोई ऐसा काम न करूँ जिससे मेरे देश की स््ववतंत्रता को, दूसरे शब््दों में, उसके सम््ममान को धक्का पहुँचे, उसकी किसी भी प्रकार की शक्‍त‍ि में कमी आए;$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1a6a00d3-0ea6-473c-8d1f-c70e1f0307b6', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$साथ ही उसके एक नागरिक के रूप में मेरा यह अधि‍कार भी हैहै कि अपने देश के सम््ममान का पूरा-पूरा भाग मुझे मिले और उसकी शक्‍त‍ियों से अपने सम््ममान की रक्ा का मुझे, जहाँ भी मैं हूँ, भरोसा रहे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('bcb1f128-326e-46c8-940a-dc030b9305ee', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अजी, भला एक आदमी अपने इतने बड़े देश के लिए कर ही क्या सकता हैहै! फिर कोई बड़ा वैैज्ञानिक हो तो वह अपने आविष्कार से ही देश को कुछ बल दे या फिर कोई बहुत बड़ा धनपति हो तो वह अपने धन का भामाशाह की तरह समय पर त्याग कर ही कुछ काम आ सकता हैहै,$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('07ace281-bdbd-4ed3-a28b-b0e506d3239d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अपने महान राष्‍ट्र की पराधीनता के दीन दिनों में जिन लोगों ने अपने रक्त से गौरवव के दीपक जलाए और जो घोर अंधकार और भयंकर बववंडरों के झकझोरों में जीवन-भर खेल, उन दीपकों को बुझने से बचाते रहे, उन््हीं में एक थे लालाजी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('75cf4745-257a-4122-bdee-aaf9cc3cd1bf', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनके व््यक्‍त‍ित््वव के गठन में, उनके परिववार, उनके पास-पड़़ोस और उनके नगर ने अपने सर्वोत्तम रत््नों की ज््ययोति उन््हें भेंटट दी थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('924832cb-96fb-412a-9892-f6bd9c2fb29f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पर संसार के देशों में घूमकर ववे अपने देश में लौटटे, तो उन््होंने अपना सारा अनुभवव एक ही ववाक्य में भरकर बिखेर दिया। वह अनुभवव ही तो वह भूकंप था, जिसने मेरी पूर््णता को एक ही ठसक में अपूर््णता की कसक से भर दिया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3d7aa962-3e65-456e-b0a4-86d2722b4b87', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$क्या सचमुच यह अनुभवव एक मानसिक भूकंप नहीं हैहै, जो मनुष्य को झकझोर कर कहे कि किसी मनुष्य के पास संसार के ही नहीं, यदि स््वर््ग के भी सब उपहार और साधन हों, पर उसका देश गुलाम हो या किसी भी दूसरे रूप में हीन हो तो ववे सारे उपहार और साधन उसे गौरवव नहीं दे सकते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6d16d928-6ed9-46c8-84d2-601f6cb60990', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस अनुभवव की छाया में मैं सोचता हूँ कि मेरा कर््तव्य हैहै कि मुझे निजी रूप में सारे संसार का राज्य भी क््यों न मिलता हो, मैं कोई ऐसा काम न करूँ जिससे मेरे देश की स््ववतंत्रता को, दूसरे शब््दों में, उसके सम््ममान को धक्का पहुँचे, उसकी किसी भी प्रकार की शक्‍त‍ि में कमी आए; साथ ही उसके एक नागरिक के रूप में मेरा यह अधि‍कार भी हैहै कि अपने देश के सम््ममान का पूरा-पूरा भाग मुझे मिले और उसकी शक्‍त‍ियों से अपने सम््ममान की रक्ा का मुझे, जहाँ भी मैं हूँ, भरोसा रहे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cbb1c60c-6a47-4fea-9e68-248906c9a63c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बेचारा अपनी ही दाल-रोटी की फिक्र में लगा हुआ हो, वह अपने देश के लिए चाहते हुए भी क्या कर सकता है?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('9f1cef65-119c-4224-b363-755e19bf227e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आपका प्रश्न विचारों को उत्तेजना देता है, इसमें कोई संदेह नहीं; पर इसमें भी संदेह नहीं कि इसमें जीवनशास्त्र का घोर अज्ञान भी भरा हुआ है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2a72fa75-d9f4-472e-9143-7822507ffec1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अरे भाई, जीवन कोई आपके मुन्ने की गुड़िया थोड़े ही है कि आप कह सकें कि बस यह है, इतना ही है। वह तो एक विशाल समुंदर का तट है, जिस पर हरेक अपने लिए स्थान पा सकता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a9a90d8f-709c-4d7b-ae96-6e833238e009', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जीवन को दर्शनशास्त्रियों ने बहुमुखी बताया है, उसकी अनेक धाराएँ हैं। सुना नहीं आपने कि जीवन एक युद्ध है और युद्ध में लड़ना ही तो काम नहीं होता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('19bec76d-dfc9-4a9f-a38f-bb2336105caf', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लड़ने वालों को रसद न पहुँचे तो वे कैसे लड़ें। किसान ही खेती न उपजाए तो रसद पहुँचाने वाले क्या करें और लो, जाने दो बड़ी-बड़ी बातें— युद्ध में जय बोलने वालों का भी महत्त्व है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('196aba59-32d4-47a6-90a7-f43577a2dbff', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कभी मैच देखने का अवसर मिला ही होगा आपको; देखा नहीं आपने कि दर्शकों की तालियों से खिलाड़ियों के पैरों में बिजली लग जाती है और गिरते खिलाड़ी उभर जाते हैं?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('508d4a94-5376-4ed3-9e42-fea615ec2f2e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कवि-सम्मेलनों और मुशायरों की सारी सफलता दाद देने वालों पर ही निर्भर करती है, इसलिए मैं अपने देश का कितना भी साधारण नागरिक क्यों न हूँ, अपने देश के सम्मान की रक्षा के लिए बहुत कुछ कर सकता हूँ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1a1bd9b0-329c-4b93-91a6-123f1728205a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अकेला चना क्या भाड़ फोड़े— यह कहावत, अपने अनुभव के आधार पर ही आपसे कह रहा हूँ— कि सौ फीसदी झूठ है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('77844a43-1bf8-43e8-8089-118fd80207fa', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इतिहास साक्षी है, बहुत बार अकेले चने ने ही भाड़ फोड़ा है और ऐसा फोड़ा है कि भाड़ खील-खील ही नहीं हो गया, उसका निशान तक ऐसा छूमंतर हुआ कि कोई यह भी न जान पाया कि वह बेचारा आखिर था कहाँ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3280e606-2470-435b-b89d-282d6bb2e7ae', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं जानता हूँ, इतिहास की गहराइयों में उतरने का समय नहीं है, पर दो छोटी कहानियाँ तो सुन ही सकते हैं आप; और कहानियाँ भी न प्रेमचंद की हैं, न अंतोन चेखव की।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2d8384ae-2348-48ab-a658-bb10880dec59', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दो युवकों के जीवन की दो घटनाएँ हैं, पर उन दो घटनाओं में वह गाँठ इतनी साफ है, जो नागरिक और देश को एक साथ बाँधती है कि आप दो बड़ी-बड़ी पुस्तकें पढ़कर भी उसे इतना साफ नहीं देख सकते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0c42d444-8a2b-4625-830c-457ce8753f06', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे देश के महान संत स्वामी रामतीर्थ एक बार जापान गए। वे रेल में यात्रा कर रहे थे कि एक दिन ऐसा हुआ कि उन्हें खाने को फल न मिले और उन दिनों फल ही उनका भोजन था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('09bda113-e74d-4dc5-9e30-8a90478d3b7f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आपका प्रश्न विचारों को उत्तेजना देता है, इसमें कोई संदेह नहीं; पर इसमें भी संदेह नहीं कि इसमें जीवनशास्त्र का घोर अज्ञान भी भरा हुआ है। अरे भाई, जीवन कोई आपके मुन्ने की गुड़िया थोड़े ही है कि आप कह सकें कि बस यह है, इतना ही है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e26c1224-7c0a-4a6a-a0ef-a3adf5a903b5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जीवन को दर्शनशास्त्रियों ने बहुमुखी बताया है, उसकी अनेक धाराएँ हैं। सुना नहीं आपने कि जीवन एक युद्ध है और युद्ध में लड़ना ही तो काम नहीं होता। लड़ने वालों को रसद न पहुँचे तो वे कैसे लड़ें।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('174784d0-9d95-42a0-a715-1bfa39a6315f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसलिए मैं अपने देश का कितना भी साधारण नागरिक क्यों न हूँ, अपने देश के सम्मान की रक्षा के लिए बहुत कुछ कर सकता हूँ। अकेला चना क्या भाड़ फोड़े— यह कहावत, अपने अनुभव के आधार पर ही आपसे कह रहा हूँ— कि सौ फीसदी झूठ है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d3f23f24-d67a-4863-af7c-4906d71c8e27', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गाड़ी एक स््टटेटेशन पर ठहरी तो वहाँ भी उन््होंने फलों की खोज की, पर ववे पा न सके। उनके मुँह से निकला– जापान में शायद अच्छे फल नहीं मिलते! एक जापानी युववक प््लेटफार््म पर खड़ा था। वह अपनी पत््ननी को रेल में बैठाने आया था, उसने यह शब्द सुन लिए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9d255553-e284-4293-b4cd-2f5871c15627', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुनते ही वह अपनी बात बीच में छोड़कर भागा और कहीं दूर से एक टटोकरी ताजे फल लाया। ववे फल उसने स््ववामी रामतीर््थ को भेंटट करते हुए कहा– लीजिए, आपको ताजे फलों की जरूरत थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0c443da7-de78-4b57-bb55-d78883cd562a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$स््ववामी जी ने समझा कि यह कोई फल बेचने ववाला हैहै और उनके दाम पूछे, पर उसने दाम लेने से इनकार कर दिया। बहुत आग्रह करने पर उसने कहा– आप इनका मूल्य देना ही चाहते हैं तो वह यह हैहै कि आप अपने देश में जाकर किसी से यह न कहिएगा कि जापान में अच्छे फल नहीं मिलते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e4b1b85c-a22a-4a07-9432-7be91ff2e99d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$स््ववामी जी युववक का यह उत्तर सुनकर मुग्ध हो गए, और ववे क्या मुग्ध हो गए, उस युववक ने अपने इस कार्य से अपने देश का गौरवव जाने कितना बढ़ा दिया!$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('805ee41b-fa7c-4d79-8d59-aab8a1547221', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस गौरवव की ऊँचाई का अनुमान आप दूसरी घटना सुनकर ही पूरी तरह लगा सकते हैं। एक दूसरे देश का निववासी एक युववक जापान में शिक्ा लेने आया। एक दिन वह सरकारी पुस्तकालय से एक पुस्तक पढ़ने को लाया जिसमें कुछ दुर््लभ चित्र थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e9ed4791-4451-4701-aed3-c343d7d8c128', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ये चित्र इस युववक ने पुस्तक में से निकाल लिए और पुस्तक ववापस कर आया। किसी जापानी विद्यार्थीी ने यह देख लिया और पुस्तकालय को इसकी सूचना दे दी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3092ee5e-5121-4ea0-adf2-98327b6eaa0f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस ने तलाशी लेकर ववे चित्र उस विद्यार्थीी के कमरे से बरामद किए और उस विद्यार्थीी को जापान से निकाल दिया गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('49f10ac9-612c-402d-babb-fe3d5374dfc1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मामला यहीं तक रहता तो कोई बात न थी। अपराधी को दंड मिलना ही चाहिए, पर मामला यहीं तक न रुका और पुस्तकालय के बाहर बोर््ड पर लिख दिया गया कि उस देश का (जिसका वह विद्यार्थीी था) कोई निववासी इस पुस्तकालय में प्रववेश नहीं कर सकता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
