  ('5302512e-a75f-41b4-9f11-51710a065aa3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बहुत आग्रह करने पर उसने कहा– आप इनका मूल्य देना ही चाहते हैं तो वह यह हैहै कि आप अपने देश में जाकर किसी से यह न कहिएगा कि जापान में अच्छे फल नहीं मिलते। स््ववामी जी युववक का यह उत्तर सुनकर मुग्ध हो गए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ad75b024-8c50-4022-92ea-7cf5c16bb980', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक दूसरे देश का निववासी एक युववक जापान में शिक्ा लेने आया। एक दिन वह सरकारी पुस्तकालय से एक पुस्तक पढ़ने को लाया जिसमें कुछ दुर््लभ चित्र थे। ये चित्र इस युववक ने पुस्तक में से निकाल लिए और पुस्तक ववापस कर आया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('407c2501-dc1c-443b-9856-3dbd6457f1ad', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$किसी जापानी विद्यार्थीी ने यह देख लिया और पुस्तकालय को इसकी सूचना दे दी। पुलिस ने तलाशी लेकर ववे चित्र उस विद्यार्थीी के कमरे से बरामद किए और उस विद्यार्थीी को जापान से निकाल दिया गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('681893c6-a7d9-427d-b16c-cfe09ab5f902', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मामला यहीं तक रहता तो कोई बात न थी। अपराधी को दंड मिलना ही चाहिए, पर मामला यहीं तक न रुका और पुस्तकालय के बाहर बोर््ड पर लिख दिया गया कि उस देश का (जिसका वह विद्यार्थीी था) कोई निववासी इस पुस्तकालय में प्रववेश नहीं कर सकता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('03ba25cd-d1d9-4ab8-bb0b-777f7e38244b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मतलब साफ है, एकदम साफ— कि जहाँ एक युवक ने अपने काम से अपने देश का सिर ऊँचा किया था, वहीं एक युवक ने अपने देश के मस्तक पर कलंक का ऐसा टीका लगाया, जो जाने कितने वर्षों तक संसार की आँखों में उसे लांछित करता रहा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('03be5a78-f4a7-41a4-be90-9eeb6362663c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इन घटनाओं से क्या यह स्पष्ट नहीं होता है कि हरेक नागरिक अपने देश के साथ बँधा हुआ है और देश की हीनता और गौरव का ही फल उसे नहीं मिलता, उसकी हीनता और गौरव का फल भी उसके देश को मिलता है?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0145cc8c-3b17-4096-a19d-cc160510882c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं अपने देश का नागरिक हूँ और मानता हूँ कि मैं अपना देश हूँ। जैसे मैं अपने लाभ और सम्मान के लिए हरेक छोटी-छोटी बात पर ध्यान देता हूँ, वैसे ही मैं अपने देश के लाभ और सम्मान के लिए भी छोटी-छोटी बातों पर ध्यान दूँ, यह मेरा कर्तव्य है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('66bb1303-03f5-4aec-a1c9-72453fc5a765', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और जैसे मैं अपने सम्मान और साधनों से अपने जीवन में सहारा पाता हूँ, वैसे ही देश के सम्मान और साधनों से भी सहारा पाऊँ, यह मेरा अधिकार है। बात यह है कि मैं और मेरा देश दो अलग चीजें तो हैं ही नहीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9c58300b-aa84-4b5f-a6f0-ace8c10eea70', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैंने जो कुछ जीवन में अध्ययन और अनुभव से सीखा है, वह यही है कि महत्व किसी कार्य की विशालता में नहीं है, उस कार्य के करने की भावना में है। बड़े से बड़ा कार्य हीन है, यदि उसके पीछे अच्छी भावना नहीं है और छोटे से छोटा कार्य भी महान है, यदि उसके पीछे अच्छी भावना है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cefe0d47-5490-41f5-83cb-bccc5ed23cbc', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$महान कमालपाशा उन दिनों अपने देश तुर्की के राष्ट्रपति थे। राजधानी में अपनी वर्षगाँठ का उत्सव समाप्त कर जब वे अपने भवन में ऊपर चले गए, तो एक देहाती बूढ़ा उन्हें वर्षगाँठ का उपहार भेंट करने आया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e76b6ba2-1615-4ab7-b9ad-8e76ad3ff9fd', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सेक्रेटरी ने कहा– अब तो समय बीत गया है। बूढ़े ने कहा– मैं तीस मील से पैदल चलकर आ रहा हूँ, इसलिए मुझे देर हो गई।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3770bfaa-5f85-4d85-a9c7-83c3568cb834', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$राष्ट्रपति तक उसकी सूचना भेजी गई, कमालपाशा विश्राम के वस्त्र बदल चुके थे, वे उन्हीं कपड़ों में नीचे चले आए और उन्होंने बूढ़े किसान का उपहार स्वीकार किया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('dc10f0a9-fef1-4b2a-b33f-0f4945c7150b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह उपहार मिट्टी की छोटी हँडिया में पाव-भर शहद था, जिसे बूढ़ा स्वयं तोड़कर लाया था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a71a9298-e599-4a7d-864b-2fce8f3a2d9e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जहाँ एक युवक ने अपने काम से अपने देश का सिर ऊँचा किया था, वहीं एक युवक ने अपने देश के मस्तक पर कलंक का ऐसा टीका लगाया, जो जाने कितने वर्षों तक संसार की आँखों में उसे लांछित करता रहा। इन घटनाओं से क्या यह स्पष्ट नहीं होता है कि हरेक नागरिक अपने देश के साथ बँधा हुआ है और देश की हीनता और गौरव का ही फल उसे नहीं मिलता, उसकी हीनता और गौरव का फल भी उसके देश को मिलता है?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('102a5ddb-6951-41a0-abee-39aa78761df7', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं अपने देश का नागरिक हूँ और मानता हूँ कि मैं अपना देश हूँ। जैसे मैं अपने लाभ और सम््ममान के लिए हरेक छोटटी-छोटटी बात पर ध््ययान देता दूँ, वैसे ही मैं अपने देश के लाभ और सम््ममान के लिए भी छोटटी-छोटटी बातों पर ध््ययान दूँ, यह मेरा कर््तव्य हैहै और जैसे मैं अपने सम््ममान और साधनों से अपने जीवन में सहारा पाता हूँ, वैसे ही देश के सम््ममान और साधनों से भी सहारा पाऊँ, यह मेरा अधिकार हैहै।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a57c4b2c-882f-46cf-99b1-3db613135271', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैंने जो कुछ जीवन में अध्ययन और अनुभवव से सीखा हैहै, वह यही हैहै कि महत्‍व किसी कार्य की विशालता में नहीं हैहै, उस कार्य के करने की भावना में हैहै। बड़े से बड़ा कार्य हीन हैहै, यदि उसके पीछे अच्छी भावना नहीं हैहै और छोटटे से छोटटा कार्य भी महान हैहै, यदि उसके पीछे अच्छी भावना हैहै।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ffc2a8e8-418a-472f-9116-51b514297b00', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$महान कमालपाशा उन दिनों अपने देश तुर्कीी के राष्‍ट्रपति थे। राजधानी में अपनी वर््षगाँठ का उत््सवव समाप्त कर जब वव े अपने भवन में ऊपर चले गए, तो एक देहाती बूढ़ा उन््हें वर््षगाँठ का उपहार भेंटट करने आया। सेक्रेटटरी ने कहा– अब तो समय बीत गया हैहै। बूढ़े ने कहा– मैं तीस मील से पैैदल चलकर आ रहा हूँ, इसलिए मुझे देर हो गई।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a4e64a4b-3ad5-4d1c-95cd-2dd5e097e5e1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$राष्‍ट्रपति तक उसकी सूचना भेजी गई, कमालपाशा विश्राम के वस्‍त्र बदल चुके थे, ववे उन््हीं कपड़ों में नीचे चले आए और उन््होंने बूढ़े किसान का उपहार स््ववीवीकार किया। यह उपहार मिटट्टटी की छोटटी हँडिया में पावव-भर शहद था, जिसे बूढ़ा स््ववयं तोड़कर लाया था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c047e13c-1f33-46ab-8b8e-7c8a708253f0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं अपने देश का नागरिक हूँ और मानता हूँ कि मैं अपना देश हूँ। जैसे मैं अपने लाभ और सम््ममान के लिए हरेक छोटटी-छोटटी बात पर ध््ययान देता दूँ, वैसे ही मैं अपने देश के लाभ और सम््ममान के लिए भी छोटटी-छोटटी बातों पर ध््ययान दूँ, यह मेरा कर््तव्य हैहै और जैसे मैं अपने सम््ममान और साधनों से अपने जीवन में सहारा पाता हूँ, वैसे ही देश के सम््ममान और साधनों से भी सहारा पाऊँ, यह मेरा अधिकार हैहै। बात यह हैहै कि मैं और मेरा देश दो अलग चीजें तो हैं ही नहीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2c36b0e2-4447-4a12-9a06-71983806aa29', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कमालपाशा ने हँडिया को स्वयं खोला और उसमें से दो उँगलियाँ भरकर चाटने के बाद तीसरी उँगली शहद में भरकर बूढ़े के मुँह में दे दी, बूढ़ा निहाल हो गया। राष्ट्रपति ने कहा– दादा, आज सर्वोत्तम उपहार तुमने ही मुझे भेंट किया क्योंकि इसमें तुम्हारे हृदय का शुद्ध प्यार है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('176c047d-edc5-4025-9f7f-de7d52e3786c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक किसान ने रंगीन सुतलियों से एक खाट बुनी और उसे रेल में रखकर वह दिल्ली लाया। दिल्ली स्टेशन से उस खाट को अपने कंधे पर रखे वह भारत के प्रधानमंत्री पंडित नेहरू की कोठी पर पहुँचा। पंडितजी कोठी से बाहर आए तो वह खाट उसने उन्हें दी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cc7735b2-3260-4a5d-b49d-d135fd9eca36', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रधानमंत्री ने उसका यह उपहार स्वीकार ही नहीं किया, अपना एक फोटो दस्तखत कर उसे स्वयं उपहार में दिया— दस्तखती फोटो के लिए देश के बड़े-बड़े लोग, विद्वान और धनी तरसते हैं! वह क्या उस मामूली खाट के बदले में दिया गया था? ना, वह तो उस खाट वाले की भावना का ही सम्मान था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5d493ef6-9c97-4dda-b733-9366d130fc64', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे देश को दो बातों की सबसे पहले और सबसे ज्यादा जरूरत है। एक शक्ति-बोध और दूसरा सौंदर्य-बोध। बस, हम यह समझ लें कि हमारा कोई भी काम ऐसा न हो जो देश में कमजोरी की भावना को बल दे या कुरुचि की भावना को ही।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8a35b44d-9797-4c31-a539-f358b203e45b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$क्या यह शहद बहुत कीमती था? क्या उसमें मोती-हीरे मिले हुए थे? ना, उस शहद के पीछे उसके लाने वाले की भावना थी जिसने उसे सौ लालों का एक लाल बना दिया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1e0bd2ab-9d07-45cc-903a-8e37ede0701b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हम अपने कार्यों को देश के अनुकूल होने की कसौटी पर कसकर चलने की आदत डालें, यह बहुत उचित है; पर हम इसमें तब तक सफल नहीं हो सकते जब तक कि हम अपने देश की भीतरी दशा को ठीक से न समझ लें और उसे हमेशा अपने सामने न रखें।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5d4d4597-82da-45ea-9e84-b20cf3469705', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$क्या आप चलती रेलों में, मुसाफिरखानों में, क्लबों में, चौपालों पर और मोटर-बसों में कभी ऐसी चर्चा करते हैं कि हमारे देश में यह नहीं हो रहा है, वह नहीं हो रहा है और गड़बड़ है?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b1e5b833-b1a4-4f9e-a14c-80a32f0b365f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जरा अपनी बात को और स्पष्ट कर दीजिए, यह आपकी राय है और मैं इससे बहुत ही खुश हूँ कि आप मुझसे यह स्पष्टता माँग रहे हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b37fc3bf-aa01-48ed-b32f-6c79b92558c9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पंडितजी को देखकर वह इतना भाव-मुग्ध हो गया कि मुँह से कुछ कह ही न सका। पंडितजी ने पूछा कि क्या चाहते हो तुम? उसने कहा, यही कि आप इसे स्वीकार करें।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('28b01e18-a211-4c2d-80b9-b3d68d0daeeb', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$क्या जी, हम यह कैसे जान सकते हैं कि हमारा काम देश के अनुकूल है या नहीं? वाह, क्या सवाल पूछा है आपने। सवाल क्या, बातचीत में आपने तो एक कीमती मोती ही जड़ दिया यह, पर इसके उत्तर में सिर्फ हाँ या ना से काम न चलेगा, मुझे थोड़ा विवरण देना पड़ेगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c079825d-b572-4093-8434-381d7d7e74f2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन्‍होंने आदेश दिया कि राष्ट्रपति की शाही कार में शाही सम्मान के साथ उनके दादा को गाँव तक पहुँचाया जाए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
