  ('55b2f33f-a441-4ff7-988f-60eac8c64978', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेखक के अनुसार, यदि आप अपने देश की तुलना दूसरे देशों से करते हैं और अपने देश को हीन सिद्ध करते हैं, तो आप देश के शक्ति-बोध को चोट पहुँचा रहे हैं। शल्य ने कर्ण के आत्मविश्वास को अर्जुन की अजेयता का उल्लेख करके कमजोर कर दिया था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
