  ('628a09e3-1430-4289-9a7f-f96ac653d3f7', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेखक के अनुसार चुनाव देश की उच्चता और हीनता की कसौटी है। जहाँ नागरिक गलत लोगों के उत्तेजक नारों में आकर मत देते हैं, वह देश हीन है। नागरिक का कर्तव्य है कि वह सही मनुष्य को मत दे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b09ba746-759c-4e26-802b-96673e2debfd', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेखक का मानना है कि मेरा मत लिए बिना कोई भी व्यक्ति अधिकार की कुर्सी पर नहीं बैठ सकता। यह मेरा अधिकार है और मेरा कर्तव्य है कि मैं सही व्यक्ति का चुनाव करूँ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
