  ('5cbeff74-b4c7-454a-9717-5bcc7dd05da5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अपने नगर में घूम-फिरकर, वहाँ के विशाल समाज का संपर्क पा, वहाँ के संचित ज्ञान-भंडार का उपयोग कर, उसे अपनी सेवाओं का दान दे, उसकी सेवाओं का सहारा पा और इस तरह एक मनुष्य से भरा-पूरा नगर बनकर मैं खड़ा हुआ था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('aa9562bd-b53c-43d2-935a-a51e08d273b1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं अपने नगर के लोगों का सम्मान करता था, वे भी मेरा सम्मान करते थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
