  ('02b14559-e3db-452c-a87e-35ba9e5c5dbb', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस तरह मैं समझ रहा था कि मैं अपने में अब पूरा हो गया हूँ, पूरा फैल गया हूँ, पूरा मनुष्य हो गया हूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d9a5f7f6-31ac-4b36-a484-2af8c5e09145', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं सोचा करता था कि मेरी मनुष्यता में अब कोई अपूर्णता नहीं रही, मुझे अब कुछ न चाहिए, जो चाहिए, वह सब मेरे पास है— मेरा घर, मेरा पड़ोस, मेरा नगर और मैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7ee6ba2c-73c5-436d-89e2-2b06cbcad6ec', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वाह कैसी सुंदर, कैसी संगठित और कैसी पूर्ण है मेरी स्थिति!$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('57501a0a-f7dc-4d46-b3d5-6540268fb496', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक दिन आनंद की इस दीवार में एक दरार पड़ गई और तब मुझे सोचना पड़ा कि अपने घर, अपने पड़ोस, अपने नगर की सीमाओं में ममता, सहारा, ज्ञान और आनंद के उपहार पाकर भी मेरी स्थिति एकदम हीन है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5acac3ea-e4de-4bf5-9f4f-e87d7083a538', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और हीन भी इतनी कि मेरा कहीं भी और कोई भी अपमान कर सकता है— एक मामूली अपराधी की तरह।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('40dd9a96-968d-4118-9849-0892bb24b7a8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और मुझे यह भी अधिकार नहीं कि मैं उस अपमान का बदला लेना तो दूर रहा, उसके लिए कहीं अपील या दया-प्रार्थना ही कर सकूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('dc810a5f-456c-4fb7-90bc-7a36cb40271d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$क्या कोई भूकंप आया था, जिससे दीवार में दरार पड़ गई? बड़े महत्व का प्रश्न है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a7627e05-ff58-446f-9c37-383143ed7e30', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस अर्थ में भी कि यह बात को खिलने का, आगे बढ़ने का अवसर देता है और इस अर्थ में भी कि ठीक समय पर पूछा गया है। ऐसे प्रश्नों का उत्तर देने में एक अपूर्व आनंद आता है, तो उत्तर यह है आपके प्रश्न का—$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('26492b52-2ad4-4041-9569-93d5cc744ce2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जी हाँ, एक भूकंप आया था, जिससे दीवार में दरार पड़ गई और लीजिए आपको कोई नया प्रश्न न पूछना पड़े, इसलिए मैं अपनी ओर से ही कह रहा हूँ कि यह दीवार थी मानसिक विचारों की;$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('55779c83-bf82-4330-b185-4066604fa8e2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसलिए यह भूकंप भी किसी प्रांत या प्रदेश में नहीं उठा, मेरे मानस में ही उठा था। मैं और मेरा देश$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('bae637f6-3fa5-49d3-82b2-3aa682587df6', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मानस में भूकंप उठा था? हाँ जी, मानस में भूकंप उठा था और भूकंप में क्या कोई धरती थोड़े ही हिली थी, आकाश थोड़े ही काँपा था, एक तेजस््ववीवी पुरुष का अनुभवव ही वह भूकंप था, जिसने मुझे हिला दिया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('169b0218-e03c-4cfa-a2d0-e8fe8ba94649', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ववे तेजस््ववीवी पुरुष थे स््वर्गीय पंजाब-केसरी लाला लाजपत राय। अपने महान राष्‍ट्र की पराधीनता के दीन दिनों में जिन लोगों ने अपने रक्त से गौरवव के दीपक जलाए और जो घोर अंधकार और भयंकर बववंडरों के झकझोरों में जीवन-भर खेल, उन दीपकों को बुझने से बचाते रहे, उन््हीं में एक थे लालाजी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a53897f9-4a80-4d97-a910-9282f2d8f8dc', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनकी कलम और ववाणी दोनों में तेजस््वविता की अद्भुत किरणें थीं। ववे उन््हीं दिनों सारे संसार में घूमे थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1e70385e-cba4-4b67-bc93-5479331c4956', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनके व््यक्‍त‍ित््वव के गठन में, उनके परिववार, उनके पास-पड़़ोस और उनके नगर ने अपने सर्वोत्तम रत््नों की ज््ययोति उन््हें भेंटट दी थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('216faa13-6108-49ed-937e-a89e5998196a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अजी, क्या बात थी उनके व््यक्‍त‍ित््वव की, क्या देखने में, क्या सुनने में! ववे एक अपूर््व मनुष्य थे। कौन था दुनिया में जिस पर ववे मिलते ही छा न जाते,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2c26d46c-8096-4981-9501-16d4a00d7d96', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पर संसार के देशों में घूमकर ववे अपने देश में लौटटे, तो उन््होंने अपना सारा अनुभवव एक ही ववाक्य में भरकर बिखेर दिया। वह अनुभवव ही तो वह भूकंप था, जिसने मेरी पूर््णता को एक ही ठसक में अपूर््णता की कसक से भर दिया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('87898ad3-3743-499c-a2d7-89eaaa533351', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनका वह अनुभवव था कि “मैं अमेरिका गया, इंग््लैंड गया, फ््राांस गया और संसार के दूसरे देशों में भी घूमा, पर जहाँ भी मैं गया, भारतवर््ष की गुलामी की लज्जा का कलंक मेरे माथे पर लगा रहा।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3c4d8df3-fde7-434b-8577-e766035dd52f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$क्या सचमुच यह अनुभवव एक मानसिक भूकंप नहीं हैहै, जो मनुष्य को झकझोर कर कहे कि किसी मनुष्य के पास संसार के ही नहीं, यदि स््वर््ग के भी सब उपहार और साधन हों, पर उसका देश गुलाम हो या किसी भी दूसरे रूप में हीन हो तो ववे सारे उपहार और साधन उसे गौरवव नहीं दे सकते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6a852179-f35b-48b2-be1a-1750d9c63818', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस अनुभवव की छाया में मैं सोचता हूँ कि मेरा कर््तव्य हैहै कि मुझे निजी रूप में सारे संसार का राज्य भी क््यों न मिलता हो, मैं कोई ऐसा काम न करूँ जिससे मेरे देश की स््ववतंत्रता को, दूसरे शब््दों में, उसके सम््ममान को धक्का पहुँचे, उसकी किसी भी प्रकार की शक्‍त‍ि में कमी आए;$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ae0ad120-bf16-4074-b172-87796b4e9142', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$साथ ही उसके एक नागरिक के रूप में मेरा यह अधि‍कार भी हैहै कि अपने देश के सम््ममान का पूरा-पूरा भाग मुझे मिले और उसकी शक्‍त‍ियों से अपने सम््ममान की रक्ा का मुझे, जहाँ भी मैं हूँ, भरोसा रहे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6856b89a-9b9e-4efb-96e0-e5fadd630464', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अजी, भला एक आदमी अपने इतने बड़े देश के लिए कर ही क्या सकता हैहै! फिर कोई बड़ा वैैज्ञानिक हो तो वह अपने आविष्कार से ही देश को कुछ बल दे या फिर कोई बहुत बड़ा धनपति हो तो वह अपने धन का भामाशाह की तरह समय पर त्याग कर ही कुछ काम आ सकता हैहै,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4af10ae4-ba00-43b7-b508-0d2f70d9ccf4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अपने महान राष्‍ट्र की पराधीनता के दीन दिनों में जिन लोगों ने अपने रक्त से गौरवव के दीपक जलाए और जो घोर अंधकार और भयंकर बववंडरों के झकझोरों में जीवन-भर खेल, उन दीपकों को बुझने से बचाते रहे, उन््हीं में एक थे लालाजी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e4aa5539-2e66-4dd4-bbbc-d4988d937909', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनकी कलम और ववाणी दोनों में तेजस््वविता की अद्भुत किरणें थीं। ववे उन््हीं दिनों सारे संसार में घूमे थे। उनके व््यक्‍त‍ित््वव के गठन में, उनके परिववार, उनके पास-पड़़ोस और उनके नगर ने अपने सर्वोत्तम रत््नों की ज््ययोति उन््हें भेंटट दी थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e3cfc092-9d02-48fa-bb14-a936463dc5a3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनका वह अनुभवव था कि “मैं अमेरिका गया, इंग््लैंड गया, फ््राांस गया और संसार के दूसरे देशों में भी घूमा, पर जहाँ भी मैं गया, भारतवर््ष की गुलामी की लज्जा का कलंक मेरे माथे पर लगा रहा।” क्या सचमुच यह अनुभवव एक मानसिक भूकंप नहीं हैहै, जो मनुष्य को झकझोर कर कहे कि किसी मनुष्य के पास संसार के ही नहीं, यदि स््वर््ग के भी सब उपहार और साधन हों, पर उसका देश गुलाम हो या किसी भी दूसरे रूप में हीन हो तो ववे सारे उपहार और साधन उसे गौरवव नहीं दे सकते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4f1af916-56a6-430e-90b1-3e75e6c5ff7d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस अनुभवव की छाया में मैं सोचता हूँ कि मेरा कर््तव्य हैहै कि मुझे निजी रूप में सारे संसार का राज्य भी क््यों न मिलता हो, मैं कोई ऐसा काम न करूँ जिससे मेरे देश की स््ववतंत्रता को, दूसरे शब््दों में, उसके सम््ममान को धक्का पहुँचे, उसकी किसी भी प्रकार की शक्‍त‍ि में कमी आए; साथ ही उसके एक नागरिक के रूप में मेरा यह अधि‍कार भी हैहै कि अपने देश के सम््ममान का पूरा-पूरा भाग मुझे मिले और उसकी शक्‍त‍ियों से अपने सम््ममान की रक्ा का मुझे, जहाँ भी मैं हूँ, भरोसा रहे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8a32ba7c-22ca-4466-886c-95e47eae2129', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बेचारा अपनी ही दाल-रोटी की फिक्र में लगा हुआ हो, वह अपने देश के लिए चाहते हुए भी क्या कर सकता है?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0cca0061-e2b1-4651-961f-bcdc09925c17', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आपका प्रश्न विचारों को उत्तेजना देता है, इसमें कोई संदेह नहीं; पर इसमें भी संदेह नहीं कि इसमें जीवनशास्त्र का घोर अज्ञान भी भरा हुआ है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f11b90a0-4e23-4f0f-9082-54f0382f7d1d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अरे भाई, जीवन कोई आपके मुन्ने की गुड़िया थोड़े ही है कि आप कह सकें कि बस यह है, इतना ही है। वह तो एक विशाल समुंदर का तट है, जिस पर हरेक अपने लिए स्थान पा सकता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ddc4c49f-5fb5-4b50-b2d7-5d4c7294bbe0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लो, एक और बात बताता हूँ आपको। जीवन को दर्शनशास्त्रियों ने बहुमुखी बताया है, उसकी अनेक धाराएँ हैं। सुना नहीं आपने कि जीवन एक युद्ध है और युद्ध में लड़ना ही तो काम नहीं होता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3c363419-6362-4182-ba75-f6983ff1ecb1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लड़ने वालों को रसद न पहुँचे तो वे कैसे लड़ें। किसान ही खेती न उपजाए तो रसद पहुँचाने वाले क्या करें और लो, जाने दो बड़ी-बड़ी बातें— युद्ध में जय बोलने वालों का भी महत्त्व है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f53f7db7-c6ed-46db-a1f5-9e56f09aecc9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हाँ जी, युद्ध में जय बोलने वालों का भी बहुत महत्त्व है। कभी मैच देखने का अवसर मिला ही होगा आपको; देखा नहीं आपने कि दर्शकों की तालियों से खिलाड़ियों के पैरों में बिजली लग जाती है और गिरते खिलाड़ी उभर जाते हैं?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ef293c1d-c621-4eec-9094-656f3ab1bdea', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कवि-सम्मेलनों और मुशायरों की सारी सफलता दाद देने वालों पर ही निर्भर करती है, इसलिए मैं अपने देश का कितना भी साधारण नागरिक क्यों न हूँ, अपने देश के सम्मान की रक्षा के लिए बहुत कुछ कर सकता हूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('df48799c-3e48-4836-815a-322ddbb89c4b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अकेला चना क्या भाड़ फोड़े— यह कहावत, अपने अनुभव के आधार पर ही आपसे कह रहा हूँ— कि सौ फीसदी झूठ है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('224746b1-5501-44e2-be7c-80c4d7cfce7d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इतिहास साक्षी है, बहुत बार अकेले चने ने ही भाड़ फोड़ा है और ऐसा फोड़ा है कि भाड़ खील-खील ही नहीं हो गया, उसका निशान तक ऐसा छूमंतर हुआ कि कोई यह भी न जान पाया कि वह बेचारा आखिर था कहाँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5e2be1c1-f244-43ad-a3b5-c5477c839f33', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं जानता हूँ, इतिहास की गहराइयों में उतरने का समय नहीं है, पर दो छोटी कहानियाँ तो सुन ही सकते हैं आप; और कहानियाँ भी न प्रेमचंद की हैं, न अंतोन चेखव की।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('afb8c4d9-c0f3-42d3-9ac4-5afd6d442c83', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दो युवकों के जीवन की दो घटनाएँ हैं, पर उन दो घटनाओं में वह गाँठ इतनी साफ है, जो नागरिक और देश को एक साथ बाँधती है कि आप दो बड़ी-बड़ी पुस्तकें पढ़कर भी उसे इतना साफ नहीं देख सकते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('35ed48c0-3443-47f1-89f6-295b2354567c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे देश के महान संत स्वामी रामतीर्थ एक बार जापान गए। वे रेल में यात्रा कर रहे थे कि एक दिन ऐसा हुआ कि उन्हें खाने को फल न मिले और उन दिनों फल ही उनका भोजन था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('dca8173e-4fab-40c5-816d-c5614bfbee9b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आपका प्रश्न विचारों को उत्तेजना देता है, इसमें कोई संदेह नहीं; पर इसमें भी संदेह नहीं कि इसमें जीवनशास्त्र का घोर अज्ञान भी भरा हुआ है। अरे भाई, जीवन कोई आपके मुन्ने की गुड़िया थोड़े ही है कि आप कह सकें कि बस यह है, इतना ही है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('39240d92-a396-4411-a5a0-6c2b5f92c135', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जीवन को दर्शनशास्त्रियों ने बहुमुखी बताया है, उसकी अनेक धाराएँ हैं। सुना नहीं आपने कि जीवन एक युद्ध है और युद्ध में लड़ना ही तो काम नहीं होता। लड़ने वालों को रसद न पहुँचे तो वे कैसे लड़ें।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a614429d-8cfb-4a85-9e8a-d5c3a9dac6ee', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसलिए मैं अपने देश का कितना भी साधारण नागरिक क्यों न हूँ, अपने देश के सम्मान की रक्षा के लिए बहुत कुछ कर सकता हूँ। अकेला चना क्या भाड़ फोड़े— यह कहावत, अपने अनुभव के आधार पर ही आपसे कह रहा हूँ— कि सौ फीसदी झूठ है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6c07e20e-4768-4ac1-bb1b-a663afbc0e9c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गाड़ी एक स््टटेटेशन पर ठहरी तो वहाँ भी उन््होंने फलों की खोज की, पर ववे पा न सके। उनके मुँह से निकला– जापान में शायद अच्छे फल नहीं मिलते! एक जापानी युववक प््लेटफार््म पर खड़ा था। वह अपनी पत््ननी को रेल में बैठाने आया था, उसने यह शब्द सुन लिए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('845c6a9c-7260-48b4-8915-f3225ac28ae3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुनते ही वह अपनी बात बीच में छोड़कर भागा और कहीं दूर से एक टटोकरी ताजे फल लाया। ववे फल उसने स््ववामी रामतीर््थ को भेंटट करते हुए कहा– लीजिए, आपको ताजे फलों की जरूरत थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e3e384d3-51d3-4328-8900-36434d712a52', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$स््ववामी जी ने समझा कि यह कोई फल बेचने ववाला हैहै और उनके दाम पूछे, पर उसने दाम लेने से इनकार कर दिया। बहुत आग्रह करने पर उसने कहा– आप इनका मूल्य देना ही चाहते हैं तो वह यह हैहै कि आप अपने देश में जाकर किसी से यह न कहिएगा कि जापान में अच्छे फल नहीं मिलते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f3fb2b29-db01-4346-b9c2-3baf9ee2c586', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$स््ववामी जी युववक का यह उत्तर सुनकर मुग्ध हो गए, और ववे क्या मुग्ध हो गए, उस युववक ने अपने इस कार्य से अपने देश का गौरवव जाने कितना बढ़ा दिया!$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6e403c4d-38b5-4bbd-9179-1b5f03d85c64', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस गौरवव की ऊँचाई का अनुमान आप दूसरी घटना सुनकर ही पूरी तरह लगा सकते हैं। एक दूसरे देश का निववासी एक युववक जापान में शिक्ा लेने आया। एक दिन वह सरकारी पुस्तकालय से एक पुस्तक पढ़ने को लाया जिसमें कुछ दुर््लभ चित्र थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('47e6d85e-cc32-48c6-8632-8fdfa39d390e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ये चित्र इस युववक ने पुस्तक में से निकाल लिए और पुस्तक ववापस कर आया। किसी जापानी विद्यार्थीी ने यह देख लिया और पुस्तकालय को इसकी सूचना दे दी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c5296acf-a21d-4684-830c-17c2503dad15', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस ने तलाशी लेकर ववे चित्र उस विद्यार्थीी के कमरे से बरामद किए और उस विद्यार्थीी को जापान से निकाल दिया गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d14e1999-b7fe-4192-8d7f-f0c636d86181', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मामला यहीं तक रहता तो कोई बात न थी। अपराधी को दंड मिलना ही चाहिए, पर मामला यहीं तक न रुका और पुस्तकालय के बाहर बोर््ड पर लिख दिया गया कि उस देश का (जिसका वह विद्यार्थीी था) कोई निववासी इस पुस्तकालय में प्रववेश नहीं कर सकता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('bbe274c5-30f7-451d-a619-128d148d532d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गाड़ी एक स््टटेटेशन पर ठहरी तो वहाँ भी उन््होंने फलों की खोज की, पर ववे पा न सके। उनके मुँह से निकला– जापान में शायद अच्छे फल नहीं मिलते! एक जापानी युववक प््लेटफार््म पर खड़ा था। वह अपनी पत््ननी को रेल में बैठाने आया था, उसने यह शब्द सुन लिए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c8ae0e51-fd01-4870-a1f3-a1afd9874102', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुनते ही वह अपनी बात बीच में छोड़कर भागा और कहीं दूर से एक टटोकरी ताजे फल लाया। ववे फल उसने स््ववामी रामतीर््थ को भेंटट करते हुए कहा– लीजिए, आपको ताजे फलों की जरूरत थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6cc612e5-c45e-4256-ac11-3773ab7dd225', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$स््ववामी जी ने समझा कि यह कोई फल बेचने ववाला हैहै और उनके दाम पूछे, पर उसने दाम लेने से इनकार कर दिया। बहुत आग्रह करने पर उसने कहा– आप इनका मूल्य देना ही चाहते हैं तो वह यह हैहै कि आप अपने देश में जाकर किसी से यह न कहिएगा कि जापान में अच्छे फल नहीं मिलते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4b85a2c5-abc3-4335-8ac2-a52f79941a04', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$स््ववामी जी युववक का यह उत्तर सुनकर मुग्ध हो गए, और ववे क्या मुग्ध हो गए, उस युववक ने अपने इस कार्य से अपने देश का गौरवव जाने कितना बढ़ा दिया! इस गौरवव की ऊँचाई का अनुमान आप दूसरी घटना सुनकर ही पूरी तरह लगा सकते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6fe7814d-8568-44b0-8c66-8ad2ea85032a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक दूसरे देश का निववासी एक युववक जापान में शिक्ा लेने आया। एक दिन वह सरकारी पुस्तकालय से एक पुस्तक पढ़ने को लाया जिसमें कुछ दुर््लभ चित्र थे। ये चित्र इस युववक ने पुस्तक में से निकाल लिए और पुस्तक ववापस कर आया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('66986681-1312-4565-9584-01638b09808c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$किसी जापानी विद्यार्थीी ने यह देख लिया और पुस्तकालय को इसकी सूचना दे दी। पुलिस ने तलाशी लेकर ववे चित्र उस विद्यार्थीी के कमरे से बरामद किए और उस विद्यार्थीी को जापान से निकाल दिया गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e04036d1-e2c4-4482-b885-89aa660e3457', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मामला यहीं तक रहता तो कोई बात न थी। अपराधी को दंड मिलना ही चाहिए, पर मामला यहीं तक न रुका और पुस्तकालय के बाहर बोर््ड पर लिख दिया गया कि उस देश का (जिसका वह विद्यार्थीी था) कोई निववासी इस पुस्तकालय में प्रववेश नहीं कर सकता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('59c08434-178d-4bad-ab6c-314ccac368b0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मतलब साफ है, एकदम साफ— कि जहाँ एक युवक ने अपने काम से अपने देश का सिर ऊँचा किया था, वहीं एक युवक ने अपने देश के मस्तक पर कलंक का ऐसा टीका लगाया, जो जाने कितने वर्षों तक संसार की आँखों में उसे लांछित करता रहा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('448c8187-35dd-47e0-8c66-074cd7103db2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इन घटनाओं से क्या यह स्पष्ट नहीं होता है कि हरेक नागरिक अपने देश के साथ बँधा हुआ है और देश की हीनता और गौरव का ही फल उसे नहीं मिलता, उसकी हीनता और गौरव का फल भी उसके देश को मिलता है?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e74e124f-8b63-403d-956f-bf7ccb7ba124', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं अपने देश का नागरिक हूँ और मानता हूँ कि मैं अपना देश हूँ। जैसे मैं अपने लाभ और सम्मान के लिए हरेक छोटी-छोटी बात पर ध्यान देता हूँ, वैसे ही मैं अपने देश के लाभ और सम्मान के लिए भी छोटी-छोटी बातों पर ध्यान दूँ, यह मेरा कर्तव्य है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2d83440e-95a3-4f19-99e4-fbbc94f1c17b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और जैसे मैं अपने सम्मान और साधनों से अपने जीवन में सहारा पाता हूँ, वैसे ही देश के सम्मान और साधनों से भी सहारा पाऊँ, यह मेरा अधिकार है। बात यह है कि मैं और मेरा देश दो अलग चीजें तो हैं ही नहीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ec739b57-7865-466f-bb18-29331a4c7174', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैंने जो कुछ जीवन में अध्ययन और अनुभव से सीखा है, वह यही है कि महत्व किसी कार्य की विशालता में नहीं है, उस कार्य के करने की भावना में है। बड़े से बड़ा कार्य हीन है, यदि उसके पीछे अच्छी भावना नहीं है और छोटे से छोटा कार्य भी महान है, यदि उसके पीछे अच्छी भावना है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('001766f2-f39d-45b4-9c89-83fe11295726', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$महान कमालपाशा उन दिनों अपने देश तुर्की के राष्ट्रपति थे। राजधानी में अपनी वर्षगाँठ का उत्सव समाप्त कर जब वे अपने भवन में ऊपर चले गए, तो एक देहाती बूढ़ा उन्हें वर्षगाँठ का उपहार भेंट करने आया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('162a5d04-e00b-498e-8c3b-f59dd5bcf394', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सेक्रेटरी ने कहा– अब तो समय बीत गया है। बूढ़े ने कहा– मैं तीस मील से पैदल चलकर आ रहा हूँ, इसलिए मुझे देर हो गई।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a07b7bb5-dcd1-4591-b386-9076e289a9f7', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$राष्ट्रपति तक उसकी सूचना भेजी गई, कमालपाशा विश्राम के वस्त्र बदल चुके थे, वे उन्हीं कपड़ों में नीचे चले आए और उन्होंने बूढ़े किसान का उपहार स्वीकार किया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0a782c96-f4a1-4fc4-b562-db0e5d4f90e2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह उपहार मिट्टी की छोटी हँडिया में पाव-भर शहद था, जिसे बूढ़ा स्वयं तोड़कर लाया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fcc1d16e-3d12-44f7-b1b7-19407816d714', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मतलब साफ है, एकदम साफ— कि जहाँ एक युवक ने अपने काम से अपने देश का सिर ऊँचा किया था, वहीं एक युवक ने अपने देश के मस्तक पर कलंक का ऐसा टीका लगाया, जो जाने कितने वर्षों तक संसार की आँखों में उसे लांछित करता रहा। इन घटनाओं से क्या यह स्पष्ट नहीं होता है कि हरेक नागरिक अपने देश के साथ बँधा हुआ है और देश की हीनता और गौरव का ही फल उसे नहीं मिलता, उसकी हीनता और गौरव का फल भी उसके देश को मिलता है?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('66bcedc6-444a-4158-b86f-f8c1cb19deab', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं अपने देश का नागरिक हूँ और मानता हूँ कि मैं अपना देश हूँ। जैसे मैं अपने लाभ और सम््ममान के लिए हरेक छोटटी-छोटटी बात पर ध््ययान देता दूँ, वैसे ही मैं अपने देश के लाभ और सम््ममान के लिए भी छोटटी-छोटटी बातों पर ध््ययान दूँ, यह मेरा कर््तव्य हैहै और जैसे मैं अपने सम््ममान और साधनों से अपने जीवन में सहारा पाता हूँ, वैसे ही देश के सम््ममान और साधनों से भी सहारा पाऊँ, यह मेरा अधिकार हैहै।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a9df1751-7f42-46aa-978a-5993efa6f90d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैंने जो कुछ जीवन में अध्ययन और अनुभवव से सीखा हैहै, वह यही हैहै कि महत्‍व किसी कार्य की विशालता में नहीं हैहै, उस कार्य के करने की भावना में हैहै। बड़े से बड़ा कार्य हीन हैहै, यदि उसके पीछे अच्छी भावना नहीं हैहै और छोटटे से छोटटा कार्य भी महान हैहै, यदि उसके पीछे अच्छी भावना हैहै।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6dae334a-88bd-4263-8fa7-bfedc78874a1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$महान कमालपाशा उन दिनों अपने देश तुर्कीी के राष्‍ट्रपति थे। राजधानी में अपनी वर््षगाँठ का उत््सवव समाप्त कर जब वव े अपने भवन में ऊपर चले गए, तो एक देहाती बूढ़ा उन््हें वर््षगाँठ का उपहार भेंटट करने आया। सेक्रेटटरी ने कहा– अब तो समय बीत गया हैहै। बूढ़े ने कहा– मैं तीस मील से पैैदल चलकर आ रहा हूँ, इसलिए मुझे देर हो गई।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('05b7a0be-180b-4d8d-8dc1-11da7834e4db', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$राष्‍ट्रपति तक उसकी सूचना भेजी गई, कमालपाशा विश्राम के वस्‍त्र बदल चुके थे, ववे उन््हीं कपड़ों में नीचे चले आए और उन््होंने बूढ़े किसान का उपहार स््ववीवीकार किया। यह उपहार मिटट्टटी की छोटटी हँडिया में पावव-भर शहद था, जिसे बूढ़ा स््ववयं तोड़कर लाया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('721debaf-5199-4d80-9fb5-e7ff7f38fc03', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बात यह हैहै कि मैं और मेरा देश दो अलग चीजें तो हैं ही नहीं। मैंने जो कुछ जीवन में अध्ययन और अनुभवव से सीखा हैहै, वह यही हैहै कि महत्‍व किसी कार्य की विशालता में नहीं हैहै, उस कार्य के करने की भावना में हैहै। बड़े से बड़ा कार्य हीन हैहै, यदि उसके पीछे अच्छी भावना नहीं हैहै और छोटटे से छोटटा कार्य भी महान हैहै, यदि उसके पीछे अच्छी भावना हैहै।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('78813a4e-b2b3-44af-984a-07010954c9f8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कमालपाशा ने हँडिया को स्वयं खोला और उसमें से दो उँगलियाँ भरकर चाटने के बाद तीसरी उँगली शहद में भरकर बूढ़े के मुँह में दे दी, बूढ़ा निहाल हो गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('916fc98f-65a0-409b-8d7f-e4caa57abdce', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$राष्ट्रपति ने कहा– दादा, आज सर्वोत्तम उपहार तुमने ही मुझे भेंट किया क्योंकि इसमें तुम्हारे हृदय का शुद्ध प्यार है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('06b94d98-6f26-41fb-9ad6-18a24420ef42', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन्‍होंने आदेश दिया कि राष्ट्रपति की शाही कार में शाही सम्मान के साथ उनके दादा को गाँव तक पहुँचाया जाए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e7d49589-74aa-465b-86bf-15b840673acb', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$क्या यह शहद बहुत कीमती था? क्या उसमें मोती-हीरे मिले हुए थे? ना, उस शहद के पीछे उसके लाने वाले की भावना थी जिसने उसे सौ लालों का एक लाल बना दिया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a8418c26-d228-4a08-bd85-bf1f25f76d16', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे देश में भी एक ऐसी ही घटना घटी थी। एक किसान ने रंगीन सुतलियों से एक खाट बुनी और उसे रेल में रखकर वह दिल्ली लाया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('30b2f261-3a0d-43b5-a577-fcbcc2c4d49d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दिल्ली स्टेशन से उस खाट को अपने कंधे पर रखे वह भारत के प्रधानमंत्री पंडित नेहरू की कोठी पर पहुँचा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2d68ac58-a570-4741-9d63-083d91fd9512', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पंडितजी कोठी से बाहर आए तो वह खाट उसने उन्हें दी। पंडितजी को देखकर वह इतना भाव-मुग्ध हो गया कि मुँह से कुछ कह ही न सका।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('35b91e35-1b40-4632-9a32-58e4bcbc24a4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रधानमंत्री ने उसका यह उपहार स्वीकार ही नहीं किया, अपना एक फोटो दस्तखत कर उसे स्वयं उपहार में दिया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ed356ba6-f839-4241-a862-11a8950dc5c7', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह तो उस खाट वाले की भावना का ही सम्मान था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e2ae362c-ca6a-4301-9b7a-5b36de6cceaf', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हम अपने कार्यों को देश के अनुकूल होने की कसौटी पर कसकर चलने की आदत डालें, यह बहुत उचित है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e9555ac6-f8c1-460a-93d3-b086319cd980', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हम इसमें तब तक सफल नहीं हो सकते जब तक कि हम अपने देश की भीतरी दशा को ठीक से न समझ लें।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a015f7f7-9284-46bc-906c-a4c1a0e2b106', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे देश को दो बातों की सबसे पहले और सबसे ज्यादा जरूरत है। एक शक्ति-बोध और दूसरा सौंदर्य-बोध।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('52da1e0c-b3bc-4a8b-8936-7d8c8a61c896', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हम यह समझ लें कि हमारा कोई भी काम ऐसा न हो जो देश में कमजोरी की भावना को बल दे या कुरुचि की भावना को ही।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('bfff534a-7e4b-4698-a1ff-86ad5c424a6f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जरा अपनी बात को और स्पष्ट कर दीजिए, यह आपकी राय है और मैं इससे बहुत ही खुश हूँ कि आप मुझसे यह स्पष्टता माँग रहे हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6d781b83-383e-4bba-8d7f-09884c9d3a44', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$क्या आप चलती रेलों में, मुसाफिरखानों में, क्लबों में, चौपालों पर और मोटर-बसों में कभी ऐसी चर्चा करते हैं कि हमारे देश में यह नहीं हो रहा है?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('752b3903-955c-4e72-8527-01a1096c6bff', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेखक के अनुसार, यदि आप अपने देश की तुलना दूसरे देशों से करते हैं और अपने देश को हीन सिद्ध करते हैं, तो आप देश के शक्ति-बोध को चोट पहुँचा रहे हैं। शल्य ने कर्ण के आत्मविश्वास को अर्जुन की अजेयता का उल्लेख करके कमजोर कर दिया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('27ff30bf-ce47-43aa-bff2-85b2f4aa7f45', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेखक ने कहा है कि केला खाकर छिलका फेंकना, कूड़ा बाहर फेंकना, गंदे शब्दों का प्रयोग करना और सार्वजनिक स्थानों पर थूकना सुरुचि और सौंदर्य को ठेस पहुँचाता है। इससे देश की संस्कृति को चोट पहुँचती है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ba48c644-538b-4236-86f7-7d341d79f7ef', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेखक के अनुसार चुनाव देश की उच्चता और हीनता की कसौटी है। जहाँ नागरिक गलत लोगों के उत्तेजक नारों में आकर मत देते हैं, वह देश हीन है। नागरिक का कर्तव्य है कि वह सही मनुष्य को मत दे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('04eff033-82b0-4d2b-8eba-81d48a1da579', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेखक का मानना है कि मेरा मत लिए बिना कोई भी व्यक्ति अधिकार की कुर्सी पर नहीं बैठ सकता। यह मेरा अधिकार है और मेरा कर्तव्य है कि मैं सही व्यक्ति का चुनाव करूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('adc3e32f-1dc3-4a91-ba93-bcb4a030a0a3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '8440f5f7-fb89-4511-ae9c-13459306af53', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेखक ने कहा है कि यदि हम अपने घर, दफ्तर और गलियों को गंदा रखते हैं, तो हम देश के सौंदर्य-बोध को आघात पहुँचाते हैं। यह कार्य देश की संस्कृति के लिए हानिकारक है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-926Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
